mapper.select:
SELECT a.id, a.emp_id AS empId, a.month, a.absent_days AS absentDays, a.late_times AS lateTimes, a.fine, e.name AS name, d.dept_name AS deptName FROM attendance a INNER JOIN employee e ON a.emp_id = e.id LEFT JOIN dept d ON e.dept_id = d.id
AND DATE_FORMAT(a.month, '%Y') = #{year}
AND DATE_FORMAT(a.month, '%Y-%m') = #{month}
AND d.dept_name = #{dept}
AND e.name LIKE CONCAT('%', #{name}, '%')
AND a.emp_id = #{empId}
ORDER BY a.month ${sortOrder}

SELECT * FROM attendance
WHERE emp_id = #{empId}
  AND DATE_FORMAT(month, '%Y-%m') = DATE_FORMAT(#{month}, '%Y-%m')
